--- from: Assets/BundleResources/Prefabs/OverseaManage/OverManegeLoungeSelectCardsDialog.prefab
---@class OverManegeLoungeSelectCardsCell
---@field Env                           	OverManegeLoungeSelectCardsCell         
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field ImgCurrentRoomCard            	UnityEngine.RectTransform               
---@field ImgComplete                   	UnityEngine.RectTransform               
---@field CommonSmallHeadNode           	UnityEngine.RectTransform               
---@field TextNumber                    	TMPro.TextMeshProUGUI                   
---@field ImgAttribute                  	Game.Native.Common.UISwitchImage        
local OverManegeLoungeSelectCardsCell = Class('OverManegeLoungeSelectCardsCell')

function OverManegeLoungeSelectCardsCell:__init()
    self._playerCardId = nil
    self._isShowTime = false
    self.Time = nil
    self.timeTextNumber = nil
end

function OverManegeLoungeSelectCardsCell:__delete()
    self._playerCardId = nil
    self._isShowTime = false
    self.timeTextNumber = nil
end

function OverManegeLoungeSelectCardsCell:Awake()
    self.Time = self.ImgComplete.transform.parent:Find("Countdown")
    self.timeTextNumber = self.Time.transform:Find("TextNumber")
    ---@type OverManegeLoungeDataProvider
    local dataProviderIns = DataProvider:GetInstance()
    self._dataProviderIns = dataProviderIns
    
end

function OverManegeLoungeSelectCardsCell:Start()
    self.__eventTimeChange = Events.AddListener(MaidCoffeeConstants.EventNames.LoungeCardEnergyTimeChange, Bind(self, self.OnEventTimeChange))
end

function OverManegeLoungeSelectCardsCell:OnDestroy()
    if self.__eventTimeChange then
        Events.RemoveListener(MaidCoffeeConstants.EventNames.LoungeCardEnergyTimeChange, self.__eventTimeChange)
        self.__eventTimeChange = nil
    end
    self.controller = nil--luabehaviour 中CSharp
    self:Delete()
    self = nil
end

--region init

--endregion


--region logic

function OverManegeLoungeSelectCardsCell:OnEventTimeChange(isChange, cafeEnergy, maxEnergy)
    local cardInfo = self._dataProviderIns:GetCardInfoByPlayerCardId(self._playerCardId)
    if cardInfo then
        local seconds = cardInfo.recoveryTime - os.time()
        local isShow = seconds > 0
        if isShow ~= self._isShowTime then
            self._isShowTime = isShow
            KTool.SetActive(self.Time.gameObject, isShow)
        end
        if isChange then
            self:FreshMood(cardInfo.cafeEnergy, cardInfo.maxEnergy)
        end
        if isShow then
            CfUtils.FillText(self.timeTextNumber, GetTimeHMS9(seconds))
        end
    elseif cafeEnergy and maxEnergy then
        self._isShowTime = false
        KTool.SetActive(self.Time.gameObject, false)
        self:FreshMood(cafeEnergy, maxEnergy)
    end
end

---FreshUI
---@param cardDojo CardDojo
---@param index number
function OverManegeLoungeSelectCardsCell:FreshUI(cardDojo, isInLounge, index)
    self._playerCardId = checkNumber(cardDojo.id)
    UICommonUtils.FillCardHeadNode(self.CommonSmallHeadNode, 1, Bind(self, self.OnClickCellAction), cardDojo, true, index)

    local cafeEnergy = checkNumber(cardDojo.cafeEnergy)
    local maxEnergy  = cardConfMgr:GetCardMoodByCardIdLevel(cardDojo.cardId, cardDojo.favorabilityLevel)
    
    KTool.SetActive(self.ImgComplete.gameObject, isInLounge and cafeEnergy == maxEnergy)
    KTool.SetActive(self.ImgCurrentRoomCard.gameObject, isInLounge)
    self:OnEventTimeChange(true, cafeEnergy, maxEnergy)
end


function OverManegeLoungeSelectCardsCell:FreshMood(cafeEnergy, maxEnergy)
    local status = MaidCoffeeUtils.GetCardMoodStatus(checkNumber(cafeEnergy))
    local ImgAttribute = self.ImgAttribute
    ImgAttribute.Status = status

    local TextNumber = self.TextNumber
    local color = MaidCoffeeConstants.CardMoodStatusColor[status] or MaidCoffeeConstants.CardMoodStatusColor[1]
    TextNumber.text = string.format("<color=%s>%s</color>/%s", color, cafeEnergy, maxEnergy)
end


--endregion


--region get/set

function OverManegeLoungeSelectCardsCell:SetCallback(cb)
    self._cb = cb
end

--endregion


--region handler

function OverManegeLoungeSelectCardsCell:OnClickCellAction(id, index)
    if self._cb then
        self._cb(index)
    end
end

